    return true;
  }

  // Even numbers are not prime
  if (n % 2 === 0) {
    return false;
  }

  // Check odd numbers up to the square root of n
  for (let I = 3; I <= Math.sqrt(n); I += 2) {
    if (n % I === 0) {
      return false;
    }
  }

  return true;
}

// Example usage
const numbers = [2, 5, 7, 11, 13];
checkPrime(numbers);
